using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class TributeChecks {
 [MenuItem("BWVR/Verify communal tributes (Play mode)")]
 public static void Verify(){if(!EditorApplication.isPlaying)throw new Exception("Enter Play mode first");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=UnityEngine.Object.FindAnyObjectByType<CreatureHybrid>();var system=UnityEngine.Object.FindAnyObjectByType<VillageTributes>();var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)field.GetValue(slice);god.Interrupt("Tribute QA");var test=new SliceState{water=100,developmentFocus=true};field.SetValue(slice,test);var residents=slice.GetComponentsInChildren<VillagerRoutine>();var origins=residents.Select(v=>v.transform.position).ToArray();var godOrigin=god.transform.position;
  // Exercise a strict majority for the current population, not the old three-person slice.
  void SetMajority(float trust){for(int i=0;i<residents.Length;i++)test.Social(i).trust=.5f;foreach(int i in Enumerable.Range(0,residents.Length).Where(i=>i!=2).Take(residents.Length/2+1))test.Social(i).trust=trust;}
  void ClearActors(){foreach(var v in residents){v.GetComponent<VillagerSocial>().ResetTask();v.GetComponent<VillagerExploration>().ResetTask();v.GetComponent<VillagerBlockPlay>().ResetTask();v.ResetTask();}}
  try{ClearActors();system.ResetWorld();test.Social(0).trust=1;test.Social(1).trust=.5f;test.Social(2).trust=.1f;system.Tick(3,false);if(test.Tribute.pending||test.Tribute.available)throw new Exception("One extreme villager triggered communal tribute");SetMajority(.79f);system.Tick(3,false);if(test.Tribute.pending)throw new Exception("Moderate sentiment passed threshold");SetMajority(.9f);system.Tick(3,true);if(test.Tribute.pending)throw new Exception("Paused village offered tribute");float crops=test.crops;system.Tick(3,false);if(!test.Tribute.pending||test.Tribute.motive!=TributeMotive.Affection||test.crops!=crops-8||system.Courier==null)throw new Exception("Affection majority did not prepare one tribute");var courier=system.Courier;for(int i=0;i<5000&&!test.Tribute.available&&courier.Active;i++)courier.Tick(.05f,false);if(!test.Tribute.available||test.Tribute.delivered!=1||test.Tribute.affection!=1||system.Basket.held)throw new Exception("Native communal delivery failed");system.Tick(100,false);if(test.crops!=crops-8||test.Tribute.delivered!=1)throw new Exception("Held mood duplicated tribute");
   // Only the creature is ticked below: move frozen couriers clear of its approach.
   var walker=god.GetComponent<IslandNavigator>();foreach(var resident in residents)resident.transform.position=system.Altar+Vector3.up*walker.world.Scale*500;
   if(!walker.world.Sample(system.Altar+Vector3.back*walker.world.Scale*10,walker.profile,15,out var approach))throw new Exception("No feast approach");god.transform.position=walker.world.ProjectFoot(approach,walker.profile);walker.ResetRoute();
   var prop=system.Basket.GetComponent<CreatureAffordance>();prop.cooldown=0;var mind=god.GetComponent<CreatureCuriosity>();god.Interrupt("Eat tribute");int individual=residents.Sum(v=>v.GetComponent<VillagerSocial>().Memory.treatsOffered);if(!mind.TryBegin(prop))throw new Exception("Creature refused delivered tribute");for(int i=0;i<2000&&mind.Current!=CreatureCuriosity.Phase.Rest;i++)mind.Tick(.05f,test);if(test.Tribute.available||system.Basket.gameObject.activeSelf||residents.Sum(v=>v.GetComponent<VillagerSocial>().Memory.treatsOffered)!=individual)throw new Exception("Communal feast incomplete or misattributed: "+mind.Current+", available="+test.Tribute.available);
   ClearActors();for(int i=0;i<residents.Length;i++){residents[i].transform.position=origins[i];residents[i].GetComponent<IslandNavigator>().ResetRoute();}test.Hybrid.time=test.Tribute.nextAt+1;SetMajority(.1f);test.Social(2).trust=.9f;system.Tick(3,false);if(!test.Tribute.pending||test.Tribute.motive!=TributeMotive.Fear)throw new Exception("Fear majority not distinguished from affection");courier=system.Courier;for(int i=0;i<5000&&!test.Tribute.available&&courier.Active;i++)courier.Tick(.05f,false);if(test.Tribute.fear!=1||test.Tribute.delivered!=2)throw new Exception("Fear tribute failed");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));if(!saved.Valid()||saved.Tribute.motive!=TributeMotive.Fear||!saved.Tribute.available)throw new Exception("Tribute state did not save");system.ResetWorld();if(!system.Basket.gameObject.activeSelf||system.Basket.held)throw new Exception("Pending feast not safely restored");saved.Tribute.nextAt=float.NaN;if(saved.Valid())throw new Exception("Invalid tribute accepted");Debug.Log("BWVR_TRIBUTE_PASS: strict majority of extreme individual sentiments; one extreme and moderate village rejected; pause; native communal carry/delivery; crops cost; cooldown and deduplication; separate affection/fear motives; feast distinct from personal gifts; saved offering and validated state");
  }finally{ClearActors();god.Interrupt("Tribute QA complete");for(int i=0;i<residents.Length;i++){residents[i].transform.position=origins[i];residents[i].GetComponent<IslandNavigator>().ResetRoute();}god.transform.position=godOrigin;god.GetComponent<IslandNavigator>().ResetRoute();field.SetValue(slice,original);system.ResetWorld();}
 }
}
}
